var APP_URL = process.env.APP_URL ?? "https://gomicale.jp";
var MIME_BY_EXT = {
  pdf: "application/pdf",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  png: "image/png",
  webp: "image/webp"
};
function resolveMimeType(objectKey, contentType) {
  if (contentType && Object.values(MIME_BY_EXT).includes(contentType)) {
    return contentType;
  }
  const ext = objectKey.split(".").pop()?.toLowerCase() ?? "";
  return MIME_BY_EXT[ext] ?? "application/pdf";
}
async function isLineLinked(userId) {
  try {
    const { data: integration } = await supabase.from("user_integrations").select("line_user_id").eq("user_id", userId).maybeSingle();
    if (integration?.line_user_id) return true;
    const { data: lineLink } = await supabase.from("line_links").select("id").eq("user_id", userId).maybeSingle();
    return !!lineLink;
  } catch (err) {
    console.warn("[isLineLinked] error, assuming not linked:", err);
    return false;
  }
}
async function issueLineLinkCode(userId) {
  try {
    await supabase.from("line_link_codes").delete().eq("user_id", userId);
    const code = String(Math.floor(1e5 + Math.random() * 9e5));
    const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1e3).toISOString();
    const { data, error } = await supabase.from("line_link_codes").insert({ user_id: userId, code, expires_at: expiresAt }).select("code").single();
    if (error || !data) {
      console.warn("[issueLineLinkCode] insert failed:", error?.message);
      return null;
    }
    return data.code;
  } catch (err) {
    console.warn("[issueLineLinkCode] error:", err);
    return null;
  }
}
